void* AllocatePoolWithHeader(size_t size) {
    // Check that the size is non-zero
    if (size == 0) {
        return NULL;
    }

    // Calculate the total size including the header
    size_t total_size = sizeof(size_t) + size;

    // Check for overflow
    if (total_size < sizeof(size_t)) {
        return NULL;
    }

    // Allocate memory using ExAllocatePoolWithTag
    void* allocated_memory = ExAllocatePoolWithTag(NonPagedPool, total_size, 'HDRP');

    if (allocated_memory == NULL) {
        return NULL;
    }

    // Store the size in the header
    size_t* header = (size_t*)allocated_memory;
    *header = size;

    // Return a pointer to the data portion
    return (void*)(header + 1);
}

void* allocate_pooled_memory(size_t size) {
    if (size == 0) {
        return NULL;
    }

    // Assume sizeof(size_t) is the size of the header
    size_t total_size = size + sizeof(size_t);

    // Check for overflow
    if (total_size < size) {
        return NULL;
    }

    void* pool_memory = ExAllocatePoolWithTag(NonPagedPool, total_size, 'MyAl');

    if (!pool_memory) {
        return NULL;
    }

    // Store the size in the header
    *(size_t*)pool_memory = size;

    // Return pointer to the data portion (after the header)
    return (void*)((size_t*)pool_memory + 1);
}

#include <wdm.h>

void* AllocateNonPagedPoolWithHeader(size_t size) {
    // Check if the requested size is non-zero
    if (size == 0) {
        return NULL;
    }

    // Calculate the total size needed for the allocation including a header
    size_t headerSize = sizeof(size_t);  // Assuming header is a size_t
    size_t totalSize = size + headerSize;

    // Check for overflow
    if (totalSize < size) {
        return NULL;
    }

    // Allocate memory using ExAllocatePoolWithTag
    void* pool = ExAllocatePoolWithTag(NonPagedPool, (ULONG)totalSize, 'MyTag');

    if (pool == NULL) {
        return NULL;
    }

    // Store the size in the header
    size_t* header = (size_t*)pool;
    *header = size;

    // Return a pointer to the data portion of the allocated block
    return (void*)(header + 1);
}

void* AllocateNonPagedPoolWithTag(size_t size) {
    if (size == 0) {
        return NULL;
    }

    // Calculate total size needed (header + size)
    size_t totalSize = sizeof(size_t) + size;
    if (totalSize < size) {
        // Overflow detected
        return NULL;
    }

    void* block = ExAllocatePoolWithTag(NonPagedPool, totalSize, 'MyTag');
    if (!block) {
        return NULL;
    }

    // Store size in header
    *(size_t*)block = size;

    // Return pointer to data portion
    return (void*)((uintptr_t)block + sizeof(size_t));
}

void* AllocatePooledMemory(size_t size) {
    // Check for zero size allocation
    if (size == 0) {
        return NULL;
    }

    // Calculate total size including header
    size_t total_size;
    // Assuming a standard header size of sizeof(size_t) for storing the allocated size
    if (sizeof(size_t) > SIZE_MAX - size) {
        return NULL; // Overflow
    }

    total_size = sizeof(size_t) + size;

    // Allocate memory with a custom tag (e.g., 'POOL')
    void* allocated_block = ExAllocatePoolWithTag(NonPagedPool, total_size, 'POOL');

    if (allocated_block == NULL) {
        return NULL; // Allocation failed
    }

    // Write the size to the header
    *(size_t*)allocated_block = size;

    // Return pointer to data portion (skip header)
    return (void*)((unsigned char*)allocated_block + sizeof(size_t));
}
